INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (3,'hotel','Pobegnite u svet obnavljanja i mira u srcu Novog Pazara uz Aqua Spa Termalni Hotel. Smestite se usred prirodne lepote regije i pronađite savršeni utočište za opuštanje i revitalizaciju. Uživajte u našem Aqua Spa centru, gde termalne vode iz dubina zemlje pružaju jedinstveno iskustvo lečenja. Naše termalne bazeni, saune i terapeutske tretmane će vas osloboditi stresa i napetosti. Naš profesionalni tim se brine da vam pruži nezaboravno iskustvo wellnessa. Naše sobe su podjednako raskošne. Svaka soba i apartman su ukusno dizajnirani i nude spoj modernog luksuza i udobnosti. Probudite se uz predivne poglede na okolni pejzaž i uživajte u miru privatnih balkona i terasa. Aqua Spa Termalni Hotel nije samo mesto za relaksaciju, već i kulinaristička destinacija. Naš restoran nudi širok izbor lokalnih i internacionalnih jela, pripremljenih od najkvalitetnijih sastojaka. Smestite se u samom srcu Novog Pazara i istražite bogatu istoriju i kulturu grada. Izvan hotela čekaju vas lokalne atrakcije, pijace i istorijski spomenici koji čine Novi Pazar jedinstvenom destinacijom. Bilo da tražite romantični beg, wellness beg ili samo opuštanje tokom puta, Aqua Spa Termalni Hotel će premašiti vaša očekivanja. Dođite i doživite harmoniju prirode i luksuza u našem izvanrednom hotelu. Rezervišite svoj boravak danas i prepustite se putovanju opuštanja i obnove.','20.54956062516278','43.156206537146346','Aqua Spa Termale',NULL,'https://res.cloudinary.com/dp7iyoyad/image/upload/v1770649127/tourist_attractions/3/uxckblumedtexlcjtwni.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770725272/tourist_attractions/3/lkjijm0tclvnyi07uwjj.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770725989/tourist_attractions/3/jcae6wwzo9plzqpq6xo9.jpg',1);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (6,'hotel','Hotel M Star Novi Pazar se nalazi u Novom Pazaru i nudi smeštaj sa 4 zvezdice sa baštom, restoranom i barom. Hotel nudi besplatan WiFi i besplatan privatni parking. Hotel će gostima pružiti klimatizovane sobe sa radnim stolom, kuvalom za vodu, mini barom, sefom, TV-om ravnog ekrana i sopstvenom kupaonicom sa tušem. U hotelu M Star Novi Pazar svaka soba je opremljena posteljinom i peškirima. Gosti ovog smeštaja mogu uživati ​​u à la carte doručku. Oblast je popularna za vožnju bicikla, a u hotelu M Star Novi Pazar možete iznajmiti automobil. Na recepciji, gdje osoblje govori njemački, engleski, hrvatski i srpski, dostupno je 24 sata dnevno vodstvo.','20.52739200292262','43.15471869862287','Hotel M Star',NULL,'https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910778/tourist_attractions/6/f435ytofwwuq8gk8zfr2.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910779/tourist_attractions/6/qf1w8nk8u5wnetmuibvp.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910780/tourist_attractions/6/sudotlxsr5g4rxrxd8qb.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910780/tourist_attractions/6/sjwrn88s9y0fre1vzey2.jpg',4);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (18,'Islamic','Islamski centar Gazilar, otvoren 13. aprila 2021. godine, predstavlja pravo osvježenje u arhitekturi i istinski pečat postignuća Mešihata Islamske zajednice. Ovaj centar, najljepši i najmoderniji ne samo u Novom Pazaru i Sandžaku, već i šire, do Stambola, zrači modernom vizijom i duhovnom svrhom. Smješten na preko 50 ari površine, Islamski centar Gazilar ima dva ključna segmenta. Džamijski prostor se proteže na površini od hiljadu kvadrata, nudeći vjernicima prostor za molitvu koji je inspirisan tradicijom, ali opremljen suvremenim sadržajima. Druga cjelina centra, sa ukupnom površinom od hiljadu kvadratnih metara, obuhvata prostore za obrazovanje sa dvije učionice, restoran, kuhinju te četiri abdesthane – dvije za muškarce i dvije za žene. Osim toga, tu su i prostorije za gasulhanu, kao i praktične mogućnosti za pranje. Centar je također opremljen sa tri mjesta za obavljanje gasula, uz mogućnost kolskog pristupa i povezanosti sa gasulhanama i parkiralištem koje obuhvata 20 mjesta. Ukupno četiri ulaza, dva pješačka i dva za vozila, omogućavaju pristup iz različitih pravaca, sa opcijom korišćenja zasebnih ulaza za javnost i administrativne svrhe. Centralni minaret visine 37 metara ukrašava južni dio centra, a blizu njega se nalazi ulaz za multifunkcionalnu salu smještenu u suterenu. Tehnička opremljenost centra je impresivna, osiguravajući optimalne uslove tokom svih godišnjih doba. Zimi, sistem podnog i radijatorskog grijanja, podržan centralnom kotlarom na pelet, održava toplotu, dok se ljeti koristi centralni sistem hlađenja sa inovativnim fencoilerima u zidovima džamijskog prostora. Napredna informaciona tehnologija omogućava nadzor i organizaciju rada kroz fleksibilni prijenos zvuka i slike širom Centra. Ovaj moderni islamski centar, nazvan Gazilar, predstavlja sveobuhvatan podsjetnik na prošlost uz viziju budućnosti, mjesto gdje se obavlja molitva, edukacija i zajedništvo, i gdje se duhovni svijet prepliće sa savremenom tehnologijom.','20.523304858154862','43.128925112343104','Islamski centar Gazilar','1c44ed34-5771-48d1-b028-1c3412024120','https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910959/tourist_attractions/18/qqjtincnojerhdpjbmne.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910960/tourist_attractions/18/dxmirfhqpkw8b8ecniqx.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770910961/tourist_attractions/18/gtvhhu9qc5qxorqxg0a0.jpg',3);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (22,'Islamic','U istorijskoj Gazi Sinan-begovoj mahali, spomenutoj još 1528. godine, nalazi se džamija sa bogatom istorijom. Dr. Ejup Mušović predlaže da je Sinan-beg, zajedno sa svojim bratom Abdullahom, moguće bio vlasnik ili zakupac rudnika u Rogozni ili Gluhavici, akumulirajući veliko bogatstvo. Oni su velikodušno posvetili svoje bogatstvo i stekli slavu kao graditelji džamija i pripadajućih objekata. Smještena u srcu Sinan-begove mahale, džamija potiče iz vremena kada je područje brojalo 17 domaćinstava 1528. godine, kasnije smanjeno na 10 domaćinstava do 1540. godine, da bi se konačno razvilo u Sinan-begovu zajednicu do 1767. godine. Ova džamija, poput drugih u Novom Pazaru, pretrpela je razaranja i požare, naročito tokom Austro-turskog rata od 1683. do 1699. godine. Godine 1728. rekonstruisao ju je niški paša Osman Topal, postavši poznata kao Osman-pašina ili Nova džamija. Dodatno je oštećena do 1809. godine, ali je doživjela restauraciju krajem 19. veka. Nakon Drugog svetskog rata, komunističke vlasti su prenamenile džamiju u skladište, uzrokujući značajan propadanje. Uprkos izazovima, džamija je opstala i konačno prošla kroz značajnu restauraciju pre oko 20 godina, čuvajući svoju veličanstvenost. Njena karakteristična munara, jedna od najlepših u regionu, ostala je netaknuta. Džamijski kompleks sada uključuje Omladinski centar "Gazi Sinan-beg", sa multimedijalnim centrom, bibliotekom, salama za sastanke i kancelarijama, služeći edukaciji mladih u verskim, društvenim i kulturnim sferama.','20.51647340787177','43.13819237601934','Gazi Sinan-Begova džamija','1c44ed34-5771-48d1-b028-1c3412024120','https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911093/tourist_attractions/22/h7eltfhqfmihbmdpeemp.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911095/tourist_attractions/22/krs0gjfku8ryuyylaowi.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911095/tourist_attractions/22/p2fqx71jvhedysj7u6sc.jpg',2);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (24,'christian','Dobrodošli u Petrovu Crkvu, dragulj srpske istorije u Novom Pazaru. Sa punim imenom, Crkva Svetih apostola Petra i Pavla, Petrova Crkva predstavlja najstariji spomenik crkvene arhitekture u Srbiji i prvobitno je bila sedište Raska eparhije. Nalazi se samo 2 km severno od centra Novog Pazara, u naselju Deževski put, odnosno Postenje. Ova crkva ima osnovu rotunde sa upisanim četvorolistom i potiče iz vremena Vizantije, dok freske iznutra datiraju iz 10., 12. i 13. veka. Na mestu gde se sada nalazi crkva nekada je stajao rano-hrišćanski objekat podignut u 7. veku. Tokom arheoloških iskopavanja unutar crkve, pronađena je kolekcija od 92 predmeta od zlata i ćilibara, smeštena unutar ostataka ilirskog kneževskog tumula iz 5. veka p. n. e. Nakon detaljnih arheoloških istraživanja, crkva je konzervirana 1960. godine.','20.5274137893496','43.16201883817038','Crkva svetih apostola','1c44ed34-5771-48d1-b028-1c3412024120','https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911236/tourist_attractions/24/wqqm0ca66xfczyyjqvl7.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911237/tourist_attractions/24/oiplfsqyzkbweezenwgu.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911238/tourist_attractions/24/u3eobie8nxentbmdn9yt.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770911239/tourist_attractions/24/yscsf8bkldevffdsbs94.webp',3);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (25,'christian','Đurđevi stupovi nisu samo kameni zidovi crkve; oni su živa istorija i duhovno nasleđe Srbije. Njihova obnova i zaštita nisu samo akt održavanja starih kamenih zidova, već i čuvanje duha i vere koji su ovde tkani vekovima. Kroz svoje vekove postojanja, oni su svedoci vere, umetnosti i istorije Srbije i nastavljaju da budu izvor inspiracije i poštovanja. Sa obnovljenim sjajem i novim životom, Đurđevi stupovi pružaju svetli primer kako istorija i duhovnost mogu da se sačuvaju i proslave u modernom svetu.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (26,'historic','Kula Motrilja je zajedno sa tvrđavom izgrađena sredinom 15. vijeka i za vrijeme svojeg postojanja prošla je kroz rekonstrukciju koju je nalozio sultan Abdul Aziz u 17. vijeku. Svojevremeno je unutar tvrđave postojao veliki broj objekata, a danas je samo Kula Motrilja očuvana u svojem originalnom obliku. Ova tvrđava sa svojom visinom od 15m, ispustima, mušarabijama i tri reda smaknutih greda impozantna je građevina koja je odolila Balkanskim i Svjetskim ratovima. S druge strane, ostaci nekadašnjih čardaka, džamija, magacina, kasarni i drugih objekata koji su omogućavali nesmetani život vojske nalaze se pod zemljom. Tvrđava je u to vreme postojala kao malo utvrđenje opasano rovom, zemljanim nasipom i zidom od uspravno pobodenih brvana. Najvećim delom tvrđavu su činile palisade i čardaci. Nakon Austro-turskog rata, oko 1692. godine kako svedoče sačuvani dokumenti, u okviru tvrđave podignut je unutrašnji grad da bi posle 1717. godine bile podignute najpre ugaone kule – tabije, a za vreme vladavine sultana Abdul Aziza, u drugoj polovini XIX veka, i kameni bedemi između kula. Ispred utvrđenja se nalazio šanac ispunjen vodom.','20.51700570314856','43.1391929067438','Kula Motrilja','1c44ed34-5771-48d1-b028-1c3412024120','https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136172/tourist_attractions/26/wg8q7qvqz1wgoyagaqxv.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136173/tourist_attractions/26/deeesb2ytd4xpfgjfoqw.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136174/tourist_attractions/26/jsek0oew9abaczfa9dze.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136175/tourist_attractions/26/jz2na8numaet2ithmapj.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136175/tourist_attractions/26/v0yejne3fo7q2cvtoj3y.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1772136176/tourist_attractions/26/ovhh4sdjdppcc9awfra0.jpg',2);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (27,'historic','Isabegov hamam, poznat i kao Novopazarski stari hamam, je javno kupatilo u neposrednoj blizini Stare čaršije, na desnoj obali reke Raške u samom središtu Jeni Bazara Novog Pazara. Hamam je dao izgraditi treći beg Osmanske provincije Bosne i glavni osnivač Sarajeva i Novog Pazara, Isa-beg Isaković, u drugoj polovini 15. veka.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (28,'natural','Gradina na Pazarištu je jedan od važnih arheoloških nalazišta koja čine deo kompleksa Stari Ras. Nalazi se na udaljenosti od 11 kilometara jugoistočno od Novog Pazara, nedaleko od manastira Sopoćani. Ovo utvrđenje se smestilo na vrhu planinskog grebena i ima karakterističan oblik nepravilnog četvorougla sa dužinom od 180 metara i širinom koja varira između 20 i 60 metara. Značajno je napomenuti da je zahvaljujući Trasnom naselju "Ras", sada omogućen lakši pristup gradini putem uređene staze koja počinje od Turističkog naselja "Ras" i proteže se na dužini od 950 metara.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (30,'hotel','Hotel Elements se nalazi u Novom Pazaru, na 3,9 km od Novopazarske banje. U ponudi je smeštaj sa restoranom, besplatnim privatnim parkingom, barom i zajedničkim salonom. Gostima ovog smeštajnog objekta su na raspolaganju skladište za prtljag i terasa. Ovaj antialergenski objekat je udaljen 7 km od Rajčinovića banje. Sobe su klimatizovane i sadrže flat-screen TV sa kablovskim kanalima, kuvalo, tuš, fen za kosu i radni sto. Hotelske sobe imaju garderober i sopstveno kupatilo. U hotelu Elements se služi kontinentalni ili à-la-carte doručak. Najbliži aerodrom je Međunarodni aerodrom Priština, udaljen 75 km od smeštajnog objekta.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (33,'hotel','Restoran Druga Priča je okružen zelenilom i rekom, na splavu koji smo gradili srcem i dušom, u potpuno novom enterijeru i ambijentu koji odišu hedonizmom.','20.550371412066443','43.15563594474873','Druga priča','1c44ed34-5771-48d1-b028-1c3412024120','https://res.cloudinary.com/dp7iyoyad/image/upload/v1770726527/tourist_attractions/33/sujit1cz1d2sx9fnbvzn.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770726527/tourist_attractions/33/q8ddydbxccpa5qapxkm9.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770726528/tourist_attractions/33/ar50rwad39crgfkbo6l9.jpg,https://res.cloudinary.com/dp7iyoyad/image/upload/v1770726529/tourist_attractions/33/kcg9zzpqmvzdl0m7guqa.jpg',1);
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (34,'hotel','Posvećeni smo zadatku da uz potpuno novo ruho hotela ne ulepšamo samo izgled, već i da podignemo standard usluge na nivo koji dolikuje luksuznom hotelu kakav je Vrbak, pružajući svojim gostima nezaboravna i nenadmašiva iskustva.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (35,'natural','U srcu jugozapadne Srbije, između planina i reka, smešten je Novi Pazar – grad bogate istorije, susreta kultura i posebne topline. Simbol tog kraja je jelek – deo tradicionalne nošnje koji ne predstavlja samo odevni predmet, već identitet, ponos i nasleđe koje se prenosi generacijama.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (36,'restaurants','Turističko naselje “Ras“ poseduje centralnu zgradu sa restoranom od 60 mesta kao i veliku salu sa 170 mesta, baštu zatvoreno tipa sa 80 mesta, letnje bašte sa 150  kao i kafe bar sa 120 mesta.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (37,'christian','Na zapadnom obodu doline reke Raške, pored samog izvora reke, među visokim i nerodnim brdima, s pretećim kamenim liticama, kralj Uroš I (1243-1276) je, po ugledu na slavne pretke, podigao sebi grobnu crkvu posvećenu Svetoj Trojici. Naziv “Sopoćani” manastir je dobio po staroslovenskoj reči “sopot”, što znači izvor.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (38,'cafe','Jazzva je prepoznatljivo mesto u gradu Novom Pazaru — kafić/bar koji spaja opuštenu atmosferu sa dobrom ponudom pića i druženja. Nalazi se u ulici Stane Bačanin i zbog svoje centralne lokacije često je središte susreta prijatelja, studenata i svih onih koji žele prijatan trenutak uz kaficu ili omiljeni napitak.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (39,'cafe','Art cafe je jedan od prepoznatljivih kafića u Novom Pazaru koji se nalazi na adresi Stevana Nemanje 116, u delu grada gde se svakodnevno okupljaju ljubitelji dobre kafe i prijatnog provoda.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (40,'cafe','Hab cafe je jedan od prepoznatljivih kafića u Novom Pazaru  u delu grada gde se svakodnevno okupljaju ljubitelji dobre kafe i prijatnog provoda.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (41,'restaurants','Art''s Diner je moderno mesto u Novom Pazaru koje je brzo postalo omiljeno među ljubiteljima dobre hrane, kafe i opuštenog provoda. Smješteno je u centralnoj ulici Stevana Nemanje, pa je lako dostupno kako lokalcima tako i posetiocima grada.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (42,'restaurants','Doha Restaurant je jedan od najpoznatijih i najposećenijih restorana u Novom Pazaru, smešten na adresi 28. novembra 54. Sa ocenom oko 4.6/5 na osnovu više od 1 200 komentara, ovo je mesto koje mnogi građani i gosti grada često biraju za doručak, ručak ili večeru.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (43,'Islamic','Altun-alem džamija (džamija sa zlatnim alemom - dragim kamenom) nalazi se u Novom Pazaru, Srbija, u Prvomajskoj ulici broj 79. Izgradio ju je osmanlija Muslihudin Abdulgani početkom 16. veka. Ona predstavlja retko remek-delo islamske arhitekture i pod zaštitom je države od 1979. godine.
INSERT INTO "TouristAttractions" ("Id","Category","Description","Latitude","Longitude","Name","OwnerId","Photos","ViewCount") VALUES (44,'cafe','Nalazimo se u srcu Novog Pazara, unutar kulturno istorijskog objekta Amir-aginog hana, čineći nas posebnom destinacijom za sve ljubitelje kafe. Kroz autentičan ambijent i vrhunsku uslugu, oživljavamo istorijski značaj ove lokacije i duh prošlih vremena. Neodoljiva kombinacija osvežavajuće mešavine kafe, mleka i karamela, savršena poslastica za hedoniste i naša najprodavanija kafa.
